class Solution {
public:
    long long maximumAlternatingSubarraySum(vector<int>& nums) {
        long long plus=LLONG_MIN/4, minus=LLONG_MIN/4, ans=LLONG_MIN;
        for (int x:nums) {
            long long nextPlus=max((long long)x,minus+x);
            long long nextMinus=plus-x;
            plus=nextPlus; minus=nextMinus;
            ans=max(ans,max(plus,minus));
        }
        return ans;
    }
};
